export function applyPreset(
  config: WebsiteConfigV1,
  name: WebsiteConfigV1["theme"]["typography"],
): WebsiteConfigV1 {
  const settings = {
    Editorial: ["#1d3557", "#f6f4f1", "pill", "generous"],
    Modern: ["#234d46", "#ffffff", "rounded", "comfortable"],
    Elegant: ["#594635", "#faf7f0", "rounded", "generous"],
    Bold: ["#9c3024", "#fffaf1", "square", "compact"],
    Classic: ["#3e4534", "#f5f2e9", "rounded", "comfortable"],
  } as const;
  const [primaryColor, backgroundColor, buttonShape, spacing] = settings[name];
  return {
    ...config,
    theme: {
      ...config.theme,
      typography: name,
      primaryColor,
      accentDark: darken(primaryColor),
      backgroundColor,
      textColor: "#191816",
      buttonShape,
      spacing,
      buttonFill: "filled",
      buttonSize: "normal",
      headingScale: name === "Bold" ? 1.2 : 1,
    },
  };
}

